package dev.quokkify.testplanit.services;

import com.fasterxml.jackson.databind.JsonNode;
import feign.Param;
import feign.RequestLine;

/**
 * TestPlanIt endpoints. Model endpoints are generated by ZenStack: reads take a JSON query in {@code q},
 * writes take a JSON body.
 */
public interface TestPlanItFeignApi {

  @RequestLine("GET /api/model/{model}/{operation}?q={query}")
  JsonNode read(@Param("model") String model, @Param("operation") String operation, @Param("query") String query);

  @RequestLine("POST /api/model/{model}/{operation}")
  JsonNode write(@Param("model") String model, @Param("operation") String operation, JsonNode body);

  @RequestLine("PATCH /api/model/{model}/update")
  JsonNode update(@Param("model") String model, JsonNode body);

  /**
   * Endpoint used by the TestPlanIt UI to add a result. Unlike {@code testRunResults/create},
   * it also updates the status of the run case.
   */
  @RequestLine("POST /api/test-runs/submit-result")
  JsonNode submitResult(JsonNode body);
}
